export function adaptResponse(response, trustedState) {
  if (!response || typeof response !== "object" || Array.isArray(response)) {
    return { event: { lifecycle: "error", code: "BAD_RESPONSE" }, context: trustedState };
  }
  if (response.error) {
    return { event: { lifecycle: "error", code: "PROVIDER_ERROR" }, context: trustedState };
  }
  if (response.status === "incomplete") {
    return { event: { lifecycle: "incomplete" }, context: trustedState };
  }
  if (containsRefusal(response.output)) {
    return { event: { lifecycle: "refusal" }, context: trustedState };
  }
  if (response.status !== "completed") {
    return { event: { lifecycle: "error", code: "NOT_COMPLETED" }, context: trustedState };
  }
  const calls = Array.isArray(response.output)
    ? response.output.filter(item => item?.type === "function_call")
    : [];
  if (calls.length !== 1) {
    return { event: { lifecycle: "error", code: "CALL_COUNT" }, context: trustedState };
  }
  return {
    event: {
      lifecycle: "complete",
      type: calls[0].type,
      name: calls[0].name,
      call_id: calls[0].call_id,
      arguments: calls[0].arguments
    },
    context: trustedState
  };
}

export function buildFunctionOutput(success) {
  if (!success?.ok || typeof success.call_id !== "string") {
    throw new TypeError("A successful correlated result is required");
  }
  return {
    type: "function_call_output",
    call_id: success.call_id,
    output: JSON.stringify(success.output)
  };
}

