import {readFileSync} from "node:fs";
const stocks = JSON.parse(readFileSync(new URL("./stocks.json", import.meta.url), "utf8"));

export function processEnvelope(event, context) {
  if (!event || typeof event !== "object" || Array.isArray(event)) return {ok:false,code:"BAD_ENVELOPE"};
  if (event.lifecycle === "refusal") return {ok:false,code:"REFUSED"};
  if (event.lifecycle === "incomplete") return {ok:false,code:"INCOMPLETE"};
  if (event.lifecycle === "error") return {ok:false,code:event.code || "PROVIDER_ERROR"};
  if (event.lifecycle !== "complete") return {ok:false,code:"NOT_COMPLETED"};
  if (event.type !== "function_call") return {ok:false,code:"BAD_CALL_TYPE"};
  if (typeof event.call_id !== "string" || event.call_id.length === 0) return {ok:false,code:"MISSING_CALL_ID"};
  if (event.name !== "lookup_stock") return {ok:false,code:"UNKNOWN_TOOL"};
  if (event.call_id !== context.expectedCallId) return {ok:false,code:"WRONG_CORRELATION"};
  if (context.authorized !== true) return {ok:false,code:"UNAUTHORIZED"};
  let args;
  try { args = JSON.parse(event.arguments); } catch { return {ok:false,code:"BAD_JSON"}; }
  if (!args || typeof args !== "object") return {ok:false,code:"BAD_SHAPE"};
  if (typeof args.ticker !== "string" || typeof args.quantity !== "number") return {ok:false,code:"BAD_TYPE"};
  const unitPrice = stocks[args.ticker]?.unitPrice;
  const total = unitPrice * args.quantity;
  return {ok:true,output:{ticker:args.ticker,unitPrice,quantity:args.quantity,total,source:"offline-fixture"},call_id:event.call_id};
}
