const fixture = JSON.parse(readFileSync(new URL("./stocks.json", import.meta.url), "utf8"));

function reject(code) { return {ok:false,code}; }
export function processEnvelope(event, trusted) {
  if (event === null || typeof event !== "object" || Array.isArray(event)) return reject("BAD_ENVELOPE");
  if (event.lifecycle === "refusal") return reject("REFUSED");
  if (event.lifecycle === "incomplete") return reject("INCOMPLETE");
  if (event.lifecycle === "error") return reject(event.code || "PROVIDER_ERROR");
  if (event.lifecycle !== "complete") return reject("NOT_COMPLETED");
  if (event.type !== "function_call") return reject("BAD_CALL_TYPE");
  if (typeof event.call_id !== "string" || event.call_id === "") return reject("MISSING_CALL_ID");
  const tools = new Set(["lookup_stock"]);
  if (!tools.has(event.name)) return reject("UNKNOWN_TOOL");
  if (!trusted || event.call_id !== trusted.expectedCallId) return reject("WRONG_CORRELATION");
  if (trusted.authorized !== true) return reject("UNAUTHORIZED");
  let value;
  try { value = JSON.parse(event.arguments); } catch { return reject("BAD_JSON"); }
  if (value === null || Array.isArray(value) || typeof value !== "object") return reject("BAD_SHAPE");
  const keys = Object.keys(value);
  if (keys.some(key => key !== "ticker" && key !== "quantity")) return reject("UNKNOWN_KEY");
  if (typeof value.ticker !== "string" || !Number.isInteger(value.quantity)) return reject("BAD_TYPE");
  if (!Object.hasOwn(fixture, value.ticker) || value.quantity < 1 || value.quantity > 100) return reject("DOMAIN");
  const unitPrice = fixture[value.ticker].unitPrice;
  return {ok:true,output:{ticker:value.ticker,unitPrice,quantity:value.quantity,total:unitPrice*value.quantity,source:"offline-fixture"},call_id:event.call_id};
}
