import {isDeepStrictEqual} from "node:util";

function complete(call_id, name, argumentsText) {
  return {lifecycle:"complete",type:"function_call",call_id,name,arguments:argumentsText};
}
function context(expectedCallId) {
  return {expectedCallId,authorized:true};
}
function deepFreeze(value) {
  if (value && typeof value === "object" && !Object.isFrozen(value)) {
    Object.freeze(value);
    for (const child of Object.values(value)) deepFreeze(child);
  }
  return value;
}

const cases = deepFreeze([
  {name:"valid",event:complete("c1","lookup_stock",'{"ticker":"ACME","quantity":2}'),context:context("c1"),expected:{ok:true,output:{ticker:"ACME",unitPrice:125,quantity:2,total:250,source:"offline-fixture"},call_id:"c1"}},
  {name:"wrongType",event:complete("c2","lookup_stock",'{"ticker":"ACME","quantity":"2"}'),context:context("c2"),expected:{ok:false,code:"BAD_TYPE"}},
  {name:"unknownKey",event:complete("c3","lookup_stock",'{"ticker":"ACME","quantity":2,"currency":"USD"}'),context:context("c3"),expected:{ok:false,code:"UNKNOWN_KEY"}},
  {name:"nullValue",event:complete("c4","lookup_stock",'null'),context:context("c4"),expected:{ok:false,code:"BAD_SHAPE"}},
  {name:"arrayValue",event:complete("c5","lookup_stock",'[]'),context:context("c5"),expected:{ok:false,code:"BAD_SHAPE"}},
  {name:"malformed",event:complete("c6","lookup_stock",'{"ticker":"ACME"'),context:context("c6"),expected:{ok:false,code:"BAD_JSON"}},
  {name:"range",event:complete("c7","lookup_stock",'{"ticker":"ACME","quantity":0}'),context:context("c7"),expected:{ok:false,code:"DOMAIN"}},
  {name:"unknownTool",event:complete("c8","delete_stock",'{"ticker":"ACME","quantity":2}'),context:context("c8"),expected:{ok:false,code:"UNKNOWN_TOOL"}},
  {name:"wrongCorrelation",event:complete("c9","lookup_stock",'{"ticker":"ACME","quantity":2}'),context:context("other"),expected:{ok:false,code:"WRONG_CORRELATION"}},
  {name:"refused",event:{lifecycle:"refusal"},context:context("c10"),expected:{ok:false,code:"REFUSED"}},
  {name:"incomplete",event:{lifecycle:"incomplete"},context:context("c11"),expected:{ok:false,code:"INCOMPLETE"}},
  {name:"changedInput",event:complete("c12","lookup_stock",'{"ticker":"BETA","quantity":3}'),context:context("c12"),expected:{ok:true,output:{ticker:"BETA",unitPrice:40,quantity:3,total:120,source:"offline-fixture"},call_id:"c12"}}
]);

const modulePath = process.argv[2] || "./student.mjs";
const implementation = await import(modulePath);
let failures = 0;
for (const test of cases) {
  let got;
  try {
    got = implementation.processEnvelope(test.event, test.context);
  } catch (error) {
    got = {ok:false,code:"CRASH",name:error?.name || "Error"};
  }
  const pass = isDeepStrictEqual(got, test.expected);
  console.log(`${pass ? "PASS" : "FAIL"} ${test.name} ${JSON.stringify(got)}`);
  if (!pass) failures++;
}
console.log(`TOTAL ${cases.length} FAILURES ${failures}`);
process.exitCode = failures === 0 ? 0 : 1;
